(() => {
  const all = document.querySelectorAll('*');
  const matches = [];
  for (const el of all) {
    if (el.children.length === 0 && (el.textContent.trim() === 'river-flash-8022' || el.textContent.trim() === 'cedar-flash-7863')) {
      const parent = el.parentElement;
      matches.push({
        text: el.textContent.trim(),
        tag: el.tagName,
        cls: el.className,
        id: el.id,
        parentTag: parent.tagName,
        parentCls: parent.className,
        parentId: parent.id
      });
    }
  }
  return matches;
})()
